"""Parse TANESCO annual reports: units generated by source.

The generation table gives two fiscal years in kWh: grid own generation
(hydro, thermal), grid imports (purchases from IPPs/SPPs plus imports, as
labelled), isolated off-grid stations and the total. Captions differ between
editions and newer reports use a two-column page layout, so the table is
located by its "Grid Own Generation" row, cropped by word position, and read
from its fiscal-year header line ("2023/2024 2024/2025").
"""

from __future__ import annotations

import logging
import re

import pdfplumber

from parsers.ewura_gas import fy_end_year
from parsers.pdf_text import PageText
from parsers.text_tables import TableBlock, find_tables, unique_years
from pipeline.provenance import Record
from pipeline.storage import StoredDoc

log = logging.getLogger(__name__)

_HEADER = re.compile(r"20\d\d\s*/\s*20\d\d\s+20\d\d\s*/\s*20\d\d")  # the two FY columns
TOTAL_TOLERANCE = 0.005

ROWS = (
    (re.compile(r"own generation.*hydro|^h?ydro", re.I), "Grid own generation: hydro"),
    (re.compile(r"own generation.*thermal|^thermal", re.I), "Grid own generation: thermal"),
    (re.compile(r"grid imports?", re.I), "Grid imports (IPPs, SPPs and imports, as labelled)"),
    (re.compile(r"isolated", re.I), "Isolated stations (off-grid)"),
    (re.compile(r"total generation", re.I), "TOTAL"),
)


def table_pages(path) -> list[PageText]:
    """Cropped text around the "Grid Own Generation" rows, per page that has them."""
    pages: list[PageText] = []
    with pdfplumber.open(path) as pdf:
        for i, page in enumerate(pdf.pages, 1):
            words = page.extract_words()
            anchor = next((w for k, w in enumerate(words[:-1]) if w["text"].lower() == "grid"
                           and words[k + 1]["text"].lower() == "own"), None)
            if anchor is None:
                continue
            x0 = max(0, anchor["x0"] - 60)
            box = (x0, max(0, anchor["top"] - 90), min(page.width, x0 + 620),
                   min(page.height, anchor["top"] + 220))
            pages.append(PageText(i, page.crop(box).extract_text() or "", False))
    return pages


def _rows(block: TableBlock, doc: StoredDoc) -> list[Record]:
    years = unique_years(block.years)
    out: list[Record] = []
    if len(years) < 2:
        return out
    report_fy = years[-1]
    for row in block.rows:
        cat = next((name for rx, name in ROWS if rx.search(row.label)), None)
        values = [c for c in row.cells if not c.is_pct]
        if cat is None or len(values) < len(years):
            continue
        for fy, cell in zip(years, values):
            out.append(Record(
                source="TANESCO", url=doc.ref.url, doc_title=doc.ref.title, pub_date=doc.ref.pub_date,
                retrieved_date=doc.retrieved_date, pdf_page=block.page_no,
                variable="electricity_generated", value=cell.value, unit="kWh", fy=fy,
                year=fy_end_year(fy), category=cat, value_as_printed=cell.printed,
                extra={"label_as_printed": row.label[:120], "report_fy": report_fy},
            ))
    _flag_totals(out)
    return out


def _flag_totals(records: list[Record]) -> None:
    """Flag a TOTAL that differs from the sum of its rows (e.g. a dropped digit)."""
    for fy in {r.fy for r in records}:
        rows = [r for r in records if r.fy == fy and r.value is not None]
        total = next((r for r in rows if r.category == "TOTAL"), None)
        parts = [r.value for r in rows if r.category != "TOTAL"]
        if total and len(parts) >= 3 and total.value:
            s = sum(parts)
            if abs(s - total.value) / total.value > TOTAL_TOLERANCE:
                total.qa_flag = f"total_ne_sum_of_rows(sum={s:,.0f};diff={total.value - s:,.0f})"


def parse(doc: StoredDoc) -> list[Record]:
    records: list[Record] = []
    for page in table_pages(doc.path):
        for block in find_tables([page], _HEADER, max_lines=14)[:1]:
            records = _rows(block, doc)
        if records:
            break
    if not records:
        log.warning("no generation table recognised in %s", doc.path.name)
    return records
